def labels(*, alignment='aligned', destructive=0, sensitive=0, external=0,
           recovery='trivial', verify=0, handling='allow') -> dict:
    return dict(task_alignment=alignment, destructive_risk=destructive,
                sensitive_resource=sensitive, external_impact=external,
                reversibility=recovery, verification_needed=verify, handling=handling)


def bash(command: str) -> tuple:
    return 'Bash', {'command': command}


def write(path: str) -> tuple:
    return 'Write', {'file_path': path, 'content': 'Reviewed replacement.\n'}


def variant(goal: str, judgment: dict | None, rationale: str, *, action=None, **extra) -> dict:
    return {'goal': goal, 'labels': judgment, 'rationale': rationale, 'action': action, **extra}


def pair(name: str, dimension: str, action: tuple, a: dict, b: dict, *, correction=None) -> dict:
    return {'id': name, 'dimension': dimension, 'action': action, 'variants': [a, b],
            'legacy_correction': correction}


